screenPanels.initJs:
function(container, apiUrl, tables) {
  // 金額計算の更新
  function updateTotalAmount() {
    const quantity = parseInt(container.querySelector('input[name="quantity"]').value) || 0;
    const unitPrice = parseInt(container.querySelector('input[name="unitPrice"]').value) || 0;
    const total = quantity * unitPrice;
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 生産ライン一覧の再描画
  function renderProductionLines(lines) {
    const tbody = container.querySelector('#production-lines-tbody');
    if (!lines || lines.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 24px; text-align: center; color: var(--text-muted); font-size: 14px;">影響を受ける生産ラインはありません</td></tr>';
      return;
    }

    tbody.innerHTML = lines.map(line => `
      <tr>
        <td style="padding: 8px; font-size: 13px; color: var(--text);">${line.lineName || ''}</td>
        <td style="padding: 8px; font-size: 13px;">
          <span style="padding: 4px 8px; border-radius: 3px; font-size: 12px; font-weight: 600; 
                       background: ${line.impactLevel === '高' ? 'rgba(255,107,107,0.2); color: #ff6b6b' : 
                                   line.impactLevel === '中' ? 'rgba(255,193,7,0.2); color: #ffc107' : 
                                   'rgba(40,167,69,0.2); color: #28a745'};">
            ${line.impactLevel || '低'}
          </span>
        </td>
        <td style="padding: 8px; font-size: 13px; color: var(--text);">${line.adjustmentDays || 0}日</td>
        <td style="padding: 8px; font-size: 13px;">
          <span style="padding: 4px 8px; border-radius: 3px; font-size: 12px; font-weight: 600;
                       background: ${line.status === '稼働中' ? 'rgba(40,167,69,0.2); color: #28a745' : 
                                   line.status === 'メンテナンス中' ? 'rgba(255,193,7,0.2); color: #ffc107' : 
                                   'rgba(108,117,125,0.2); color: #6c757d'};">
            ${line.status || '稼働中'}
          </span>
        </td>
      </tr>
    `).join('');
  }

  // 影響度判定の実行
  async function analyzeImpact() {
    const formData = new FormData(container.querySelector('#order-form'));
    const productId = formData.get('productId');
    const quantity = parseInt(formData.get('quantity')) || 0;
    const deliveryDate = formData.get('deliveryDate');

    if (!productId || !quantity || !deliveryDate) {
      alert('製品、数量、納期を入力してください');
      return;
    }

    // 生産ライン情報を取得
    const productionLines = await window.aivicApi.list(6); // 生産ラインテーブル
    if (!productionLines) {
      alert('生産ライン情報の取得に失敗しました');
      return;
    }

    // 生産計画情報を取得
    const productionPlans = await window.aivicApi.list(5); // 生産計画テーブル

    // 影響度を計算（簡易ロジック）
    const affectedLines = productionLines.filter(line => {
      // 同じ製品を生産するラインを対象
      return line.productId === productId || Math.random() > 0.6; // デモ用ランダム
    }).map(line => {
      const impactLevel = quantity > 100 ? '高' : quantity > 50 ? '中' : '低';
      const adjustmentDays = quantity > 100 ? Math.ceil(quantity / 50) : Math.ceil(quantity / 100);

      return {
        ...line,
        impactLevel,
        adjustmentDays,
        status: line.稼働状況 || '稼働中'
      };
    });

    // 全体の影響度レベルを決定
    const hasHighImpact = affectedLines.some(line => line.impactLevel === '高');
    const hasMediumImpact = affectedLines.some(line => line.impactLevel === '中');

    let overallImpact, impactColor, summary;
    if (hasHighImpact) {
      overallImpact = '高';
      impactColor = 'rgba(255,107,107,0.2); color: #ff6b6b';
      summary = `${affectedLines.length}つの生産ラインに大きな影響があります。生産計画の大幅な調整が必要です。`;
    } else if (hasMediumImpact) {
      overallImpact = '中';
      impactColor = 'rgba(255,193,7,0.2); color: #ffc107';
      summary = `${affectedLines.length}つの生産ラインに中程度の影響があります。部分的な調整が必要です。`;
    } else {
      overallImpact = '低';
      impactColor = 'rgba(40,167,69,0.2); color: #28a745';
      summary = `影響は軽微です。現在の生産計画で対応可能です。`;
    }

    // 結果を表示
    const impactLevelEl = container.querySelector('#impact-level');
    impactLevelEl.textContent = overallImpact;
    impactLevelEl.style.background = impactColor.split(';')[0];
    impactLevelEl.style.color = impactColor.split(';')[1].replace('color:', '').trim();

    container.querySelector('#impact-summary').textContent = summary;
    renderProductionLines(affectedLines);
  }

  // 受注登録の実行
  async function saveOrder() {
    const formData = new FormData(container.querySelector('#order-form'));
    const orderData = {
      顧客ID: formData.get('customerId'),
      受注日: formData.get('orderDate'),
      納期: formData.get('deliveryDate'),
      受注金額: parseInt(formData.get('quantity')) * parseInt(formData.get('unitPrice')) || 0,
      受注ステータス: '受注確定',
      担当営業ID: 'current-user-id',
      備考: formData.get('notes')
    };

    const detailData = {
      製品ID: formData.get('productId'),
      明細番号: 1,
      数量: parseInt(formData.get('quantity')) || 0,
      単価: parseInt(formData.get('unitPrice')) || 0,
      金額: orderData.受注金額,
      備考: formData.get('notes')
    };

    if (!orderData.顧客ID || !orderData.受注日 || !orderData.納期 || !detailData.製品ID || !detailData.数量) {
      alert('必須項目を入力してください');
      return;
    }

    // 受注を保存
    const savedOrder = await window.aivicApi.save(4, orderData); // 受注テーブル
    if (savedOrder) {
      detailData.受注ID = savedOrder.id;
      const savedDetail = await window.aivicApi.save(5, detailData); // 受注明細テーブル

      if (savedDetail) {
        alert('受注を登録しました');
        container.querySelector('#order-form').reset();
        updateTotalAmount();

        // 影響度判定結果をリセット
        container.querySelector('#impact-level').textContent = '未判定';
        container.querySelector('#impact-level').style.background = 'rgba(128,128,128,0.2)';
        container.querySelector('#impact-level').style.color = 'var(--text)';
        container.querySelector('#impact-summary').textContent = '影響度判定ボタンをクリックして分析を実行してください';
        renderProductionLines([]);
      }
    }
  }

  // イベントリスナーの設定
  container.querySelector('input[name="quantity"]').addEventListener('input', updateTotalAmount);
  container.querySelector('input[name="unitPrice"]').addEventListener('input', updateTotalAmount);

  container.querySelector('#btn-analyze').addEventListener('click', analyzeImpact);
  container.querySelector('#btn-save').addEventListener('click', saveOrder);

  // 初期化
  updateTotalAmount();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('input[name="orderDate"]').value = today;
}

function(container, apiUrl, tables) {
  let currentOrders = [];
  let currentCustomerId = '';

  // テーブル再描画関数
  function renderOrderHistory(orders) {
    const tbody = container.querySelector('#order-history-tbody');
    tbody.innerHTML = orders.map(order => {
      const orderDate = new Date(order.受注日).toLocaleDateString('ja-JP');
      const deliveryDate = new Date(order.納期).toLocaleDateString('ja-JP');
      const amount = (order.受注金額 || 0).toLocaleString();
      const profitRate = order.利益率 ? `${order.利益率}%` : '-';

      return `
        <tr data-id="${order.受注ID}">
          <td>${orderDate}</td>
          <td>${order.受注番号 || ''}</td>
          <td>${order.製品名 || ''}</td>
          <td>${order.カテゴリ || ''}</td>
          <td>${order.数量 || 0}</td>
          <td>¥${amount}</td>
          <td>${profitRate}</td>
          <td><span style="padding: 2px 8px; border-radius: 12px; font-size: 11px; background: rgba(0,150,255,0.15); color: #4a9eff;">${order.受注ステータス || ''}</span></td>
          <td>${deliveryDate}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${order.受注ID}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // KPI更新関数
  function updateKPIs(orders) {
    const totalAmount = orders.reduce((sum, order) => sum + (order.受注金額 || 0), 0);
    const totalOrders = orders.length;
    const avgUnitPrice = totalOrders > 0 ? Math.round(totalAmount / totalOrders) : 0;
    const avgProfitRate = orders.length > 0 ? 
      Math.round(orders.reduce((sum, order) => sum + (order.利益率 || 0), 0) / orders.length) : 0;

    container.querySelector('#total-amount').textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector('#total-orders').textContent = `${totalOrders}件`;
    container.querySelector('#avg-unit-price').textContent = `¥${avgUnitPrice.toLocaleString()}`;
    container.querySelector('#avg-profit-rate').textContent = `${avgProfitRate}%`;
  }

  // グラフ描画関数
  function drawAmountTrendChart(orders) {
    const canvas = container.querySelector('#amount-trend-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (orders.length === 0) return;

    // 月別集計
    const monthlyData = {};
    orders.forEach(order => {
      const month = new Date(order.受注日).toISOString().slice(0, 7);
      monthlyData[month] = (monthlyData[month] || 0) + (order.受注金額 || 0);
    });

    const months = Object.keys(monthlyData).sort();
    const amounts = months.map(month => monthlyData[month]);

    if (months.length === 0) return;

    const maxAmount = Math.max(...amounts);
    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#666';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ線描画
    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();

    months.forEach((month, index) => {
      const x = padding + (index / (months.length - 1)) * chartWidth;
      const y = canvas.height - padding - (amounts[index] / maxAmount) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '11px sans-serif';
    months.forEach((month, index) => {
      const x = padding + (index / (months.length - 1)) * chartWidth;
      ctx.fillText(month.slice(5), x - 15, canvas.height - 20);
    });
  }

  function drawProductCompositionChart(orders) {
    const canvas = container.querySelector('#product-composition-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (orders.length === 0) return;

    // カテゴリ別集計
    const categoryData = {};
    orders.forEach(order => {
      const category = order.カテゴリ || '未分類';
      categoryData[category] = (categoryData[category] || 0) + (order.受注金額 || 0);
    });

    const categories = Object.keys(categoryData);
    const total = Object.values(categoryData).reduce((sum, val) => sum + val, 0);

    if (total === 0) return;

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(centerX, centerY) - 20;

    const colors = ['#4a9eff', '#ff6b6b', '#51cf66', '#ffd43b', '#845ef7'];

    let currentAngle = -Math.PI / 2;

    categories.forEach((category, index) => {
      const angle = (categoryData[category] / total) * 2 * Math.PI;

      ctx.fillStyle = colors[index % colors.length];
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + angle);
      ctx.closePath();
      ctx.fill();

      // ラベル
      const labelAngle = currentAngle + angle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius + 15);
      const labelY = centerY + Math.sin(labelAngle) * (radius + 15);

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(category, labelX, labelY);

      currentAngle += angle;
    });
  }

  function drawProfitTrendChart(orders) {
    const canvas = container.querySelector('#profit-trend-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (orders.length === 0) return;

    // 月別利益率平均
    const monthlyProfit = {};
    const monthlyCount = {};

    orders.forEach(order => {
      if (order.利益率) {
        const month = new Date(order.受注日).toISOString().slice(0, 7);
        monthlyProfit[month] = (monthlyProfit[month] || 0) + order.利益率;
        monthlyCount[month] = (monthlyCount[month] || 0) + 1;
      }
    });

    const months = Object.keys(monthlyProfit).sort();
    const profitRates = months.map(month => monthlyProfit[month] / monthlyCount[month]);

    if (months.length === 0) return;

    const maxRate = Math.max(...profitRates);
    const minRate = Math.min(...profitRates);
    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#666';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ線描画
    ctx.strokeStyle = '#51cf66';
    ctx.lineWidth = 2;
    ctx.beginPath();

    months.forEach((month, index) => {
      const x = padding + (index / (months.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((profitRates[index] - minRate) / (maxRate - minRate)) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();
  }

  function drawFrequencyChart(orders) {
    const canvas = container.querySelector('#frequency-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (orders.length === 0) return;

    // 月別受注件数
    const monthlyCount = {};
    orders.forEach(order => {
      const month = new Date(order.受注日).toISOString().slice(0, 7);
      monthlyCount[month] = (monthlyCount[month] || 0) + 1;
    });

    const months = Object.keys(monthlyCount).sort();
    const counts = months.map(month => monthlyCount[month]);

    if (months.length === 0) return;

    const maxCount = Math.max(...counts);
    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / months.length * 0.8;

    // 軸描画
    ctx.strokeStyle = '#666';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // バー描画
    ctx.fillStyle = '#ffd43b';
    months.forEach((month, index) => {
      const x = padding + (index / months.length) * chartWidth + (chartWidth / months.length - barWidth) / 2;
      const barHeight = (counts[index] / maxCount) * chartHeight;
      const y = canvas.height - padding - barHeight;

      ctx.fillRect(x, y, barWidth, barHeight);

      // ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(month.slice(5), x + barWidth / 2, canvas.height - 20);
      ctx.fillStyle = '#ffd43b';
    });
  }

  // 分析実行
  async function performAnalysis() {
    const customerId = container.querySelector('#customer-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    if (!customerId) {
      alert('顧客を選択してください');
      return;
    }

    currentCustomerId = customerId;

    try {
      // 受注データ取得
      const orders = await window.aivicApi.list(4); // 受注テーブル
      const orderDetails = await window.aivicApi.list(5); // 受注明細テーブル
      const products = await window.aivicApi.list(3); // 製品テーブル
      const profitHistory = await window.aivicApi.list(10); // 利益率履歴テーブル

      if (!orders || !orderDetails || !products) {
        console.error('データ取得に失敗しました');
        return;
      }

      // 顧客・期間でフィルタリング
      const filteredOrders = orders.filter(order => {
        const orderDate = new Date(order.受注日);
        const start = new Date(startDate);
        const end = new Date(endDate);

        return order.顧客ID === customerId && 
               orderDate >= start && 
               orderDate <= end;
      });

      // 受注明細と製品情報を結合
      const enrichedOrders = filteredOrders.map(order => {
        const details = orderDetails.filter(detail => detail.受注ID === order.受注ID);
        const mainDetail = details[0] || {};
        const product = products.find(p => p.製品ID === mainDetail.製品ID) || {};
        const profit = profitHistory.find(p => p.受注ID === order.受注ID) || {};

        return {
          ...order,
          製品名: product.製品名,
          カテゴリ: product.カテゴリ,
          数量: mainDetail.数量,
          利益率: profit.利益率
        };
      });

      currentOrders = enrichedOrders;

      // 表示更新
      renderOrderHistory(currentOrders);
      updateKPIs(currentOrders);
      drawAmountTrendChart(currentOrders);
      drawProductCompositionChart(currentOrders);
      drawProfitTrendChart(currentOrders);
      drawFrequencyChart(currentOrders);

    } catch (error) {
      console.error('分析実行エラー:', error);
    }
  }

  // フィルタリング
  function applyFilters() {
    const categoryFilter = container.querySelector('#category-filter').value;
    const statusFilter = container.querySelector('#status-filter').value;

    let filtered = currentOrders;

    if (categoryFilter) {
      filtered = filtered.filter(order => order.カテゴリ === categoryFilter);
    }

    if (statusFilter) {
      filtered = filtered.filter(order => order.受注ステータス === statusFilter);
    }

    renderOrderHistory(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentOrders.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['受注日', '受注番号', '製品名', 'カテゴリ', '数量', '受注金額', '利益率', 'ステータス', '納期'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...currentOrders.map(order => [
        new Date(order.受注日).toLocaleDateString('ja-JP'),
        order.受注番号 || '',
        order.製品名 || '',
        order.カテゴリ || '',
        order.数量 || 0,
        order.受注金額 || 0,
        order.利益率 || '',
        order.受注ステータス || '',
        new Date(order.納期).toLocaleDateString('ja-JP')
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `顧客別受注履歴_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 初期データ表示
  renderOrderHistory(tables[4]?.records || []);

  // イベントリスナー
  container.querySelector('#btn-analyze').addEventListener('click', performAnalysis);
  container.querySelector('#category-filter').addEventListener('change', applyFilters);
  container.querySelector('#status-filter').addEventListener('change', applyFilters);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 行クリックイベント
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const orderId = detailBtn.dataset.id;
      window.showScreen('scr-1780996186885'); // 受注情報照会画面
    }
  });
}

function(container, apiUrl, tables) {
  // チャート描画関数
  function drawPriceChart() {
    const canvas = container.querySelector('#price-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // グリッド線
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 6; i++) {
      const y = (canvas.height / 6) * i;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(canvas.width, y);
      ctx.stroke();
    }

    // 価格推移線
    const priceData = [75000, 78000, 82000, 85000, 83000, 87000, 85000, 88000];
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();

    for (let i = 0; i < priceData.length; i++) {
      const x = (canvas.width / (priceData.length - 1)) * i;
      const y = canvas.height - ((priceData[i] - 70000) / 20000) * canvas.height;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#3b82f6';
    for (let i = 0; i < priceData.length; i++) {
      const x = (canvas.width / (priceData.length - 1)) * i;
      const y = canvas.height - ((priceData[i] - 70000) / 20000) * canvas.height;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  function drawProfitChart() {
    const canvas = container.querySelector('#profit-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // グリッド線
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 6; i++) {
      const y = (canvas.height / 6) * i;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(canvas.width, y);
      ctx.stroke();
    }

    // 利益率推移線
    const profitData = [22.5, 24.1, 26.3, 28.7, 25.9, 30.2, 28.4, 32.1];
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 2;
    ctx.beginPath();

    for (let i = 0; i < profitData.length; i++) {
      const x = (canvas.width / (profitData.length - 1)) * i;
      const y = canvas.height - ((profitData[i] - 20) / 15) * canvas.height;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#10b981';
    for (let i = 0; i < profitData.length; i++) {
      const x = (canvas.width / (profitData.length - 1)) * i;
      const y = canvas.height - ((profitData[i] - 20) / 15) * canvas.height;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  function drawCompetitorChart() {
    const canvas = container.querySelector('#competitor-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 競合価格バー
    const competitors = [
      { name: '自社', price: 85000, color: '#3b82f6' },
      { name: 'A社', price: 92000, color: '#ef4444' },
      { name: 'B社', price: 78000, color: '#f59e0b' },
      { name: 'C社', price: 88000, color: '#8b5cf6' }
    ];

    const barWidth = canvas.width / competitors.length * 0.6;
    const maxPrice = 100000;

    competitors.forEach((comp, i) => {
      const x = (canvas.width / competitors.length) * i + (canvas.width / competitors.length - barWidth) / 2;
      const height = (comp.price / maxPrice) * canvas.height * 0.8;
      const y = canvas.height - height;

      ctx.fillStyle = comp.color;
      ctx.fillRect(x, y, barWidth, height);

      // ラベル
      ctx.fillStyle = '#d1d5db';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(comp.name, x + barWidth / 2, canvas.height - 5);
      ctx.fillText(`¥${(comp.price / 1000).toFixed(0)}K`, x + barWidth / 2, y - 5);
    });
  }

  function drawDistributionChart() {
    const canvas = container.querySelector('#distribution-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 価格帯別売上
    const distribution = [
      { range: '50K未満', sales: 8.5, color: '#ef4444' },
      { range: '50-70K', sales: 15.2, color: '#f59e0b' },
      { range: '70-90K', sales: 28.7, color: '#10b981' },
      { range: '90-110K', sales: 32.1, color: '#3b82f6' },
      { range: '110K以上', sales: 15.5, color: '#8b5cf6' }
    ];

    const barWidth = canvas.width / distribution.length * 0.7;
    const maxSales = 35;

    distribution.forEach((dist, i) => {
      const x = (canvas.width / distribution.length) * i + (canvas.width / distribution.length - barWidth) / 2;
      const height = (dist.sales / maxSales) * canvas.height * 0.8;
      const y = canvas.height - height;

      ctx.fillStyle = dist.color;
      ctx.fillRect(x, y, barWidth, height);

      // ラベル
      ctx.fillStyle = '#d1d5db';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(dist.range, x + barWidth / 2, canvas.height - 5);
      ctx.fillText(`¥${dist.sales}M`, x + barWidth / 2, y - 5);
    });
  }

  // 製品別利益率テーブル再描画
  function renderProductProfitTable(products) {
    const tbody = container.querySelector('#product-profit-tbody');
    tbody.innerHTML = products.map(p => `
      <tr>
        <td>${p.製品名 || ''}</td>
        <td class="text-right ${(p.利益率 || 0) > 25 ? 'text-green-400' : 'text-yellow-400'}">${(p.利益率 || 0).toFixed(1)}%</td>
        <td class="text-right">¥${((p.売上金額 || 0) / 1000000).toFixed(1)}M</td>
      </tr>
    `).join('');
  }

  // 顧客別価格履歴テーブル再描画
  function renderCustomerPriceTable(prices) {
    const tbody = container.querySelector('#customer-price-tbody');
    tbody.innerHTML = prices.map(p => `
      <tr>
        <td>${p.顧客名 || ''}</td>
        <td>${p.製品名 || ''}</td>
        <td class="text-right">¥${(p.単価 || 0).toLocaleString()}</td>
        <td>${p.適用開始日 ? new Date(p.適用開始日).toLocaleDateString('ja-JP') : ''}</td>
      </tr>
    `).join('');
  }

  // 初期データ読み込み・描画
  async function loadInitialData() {
    try {
      // 利益率履歴データ取得
      const profitHistory = await window.aivicApi.list(9);
      if (profitHistory) {
        renderProductProfitTable(profitHistory.slice(0, 10));
      }

      // 価格履歴データ取得
      const priceHistory = await window.aivicApi.list(1);
      if (priceHistory) {
        renderCustomerPriceTable(priceHistory.slice(0, 10));
      }

      // チャート描画
      drawPriceChart();
      drawProfitChart();
      drawCompetitorChart();
      drawDistributionChart();

    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 分析実行ボタン
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const productId = container.querySelector('#product-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const period = container.querySelector('#period-select').value;

    // 分析パラメータに基づいてデータを再取得・再描画
    await loadInitialData();

    // KPI更新（実際の計算ロジックは省略）
    container.querySelector('#avg-profit-rate').textContent = '26.8%';
    container.querySelector('#total-revenue').textContent = '¥52.1M';
    container.querySelector('#top-product').textContent = 'センサー A100';
    container.querySelector('#price-changes').textContent = '21回';
  });

  // エクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const profitData = await window.aivicApi.list(9);
      const priceData = await window.aivicApi.list(1);

      if (!profitData || !priceData) return;

      // CSV生成
      const csvContent = '\uFEFF' + [
        '製品名,利益率(%),売上金額,適用開始日,単価',
        ...profitData.map(row => [
          row.製品名 || '',
          (row.利益率 || 0).toFixed(1),
          row.売上金額 || 0,
          row.集計期間開始日 || '',
          row.単価 || 0
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `価格利益率分析_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

    } catch (error) {
      console.error('エクスポートエラー:', error);
    }
  });

  // 期間比較ボタン
  container.querySelector('#btn-compare').addEventListener('click', () => {
    // 期間比較画面への遷移
    window.showScreen('scr-1780996227880');
  });

  // 初期化実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  // グラフ描画関数
  function drawPriceChart(type = 'competitor') {
    const canvas = container.querySelector('#price-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフデータ（サンプル）
    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const competitorData = [85000, 87000, 86500, 88000, 92000, 89000];
    const selfData = [80000, 82000, 83000, 85000, 87000, 87000];

    const data = type === 'competitor' ? competitorData : selfData;
    const color = type === 'competitor' ? '#ff6a00' : '#22c55e';

    // グラフ描画エリア
    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ描画
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.beginPath();

    const maxValue = Math.max(...data);
    const minValue = Math.min(...data);
    const valueRange = maxValue - minValue || 1;

    for (let i = 0; i < data.length; i++) {
      const x = padding + (i * chartWidth) / (data.length - 1);
      const y = canvas.height - padding - ((data[i] - minValue) / valueRange) * chartHeight;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // データポイント
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    }
    ctx.stroke();

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';

    for (let i = 0; i < months.length; i++) {
      const x = padding + (i * chartWidth) / (months.length - 1);
      ctx.fillText(months[i], x, canvas.height - 10);
    }
  }

  // 競合価格情報再描画
  function renderCompetitorPrices(rows) {
    const tbody = container.querySelector('#competitor-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr>
        <td class="py-1 px-2" style="color: var(--text);">${r.競合会社名 || ''}</td>
        <td class="py-1 px-2" style="color: var(--text);">${r.競合製品名 || ''}</td>
        <td class="py-1 px-2 text-right" style="color: var(--text);">¥${(r.価格 || 0).toLocaleString()}</td>
        <td class="py-1 px-2" style="color: var(--text-muted);">${r.価格取得日 ? new Date(r.価格取得日).toLocaleDateString('ja-JP') : ''}</td>
      </tr>
    `).join('');
  }

  // 原価情報更新
  function updateCostInfo(productId) {
    if (!productId) return;

    window.aivicApi.list(7).then(costs => {
      const cost = costs.find(c => c.製品ID === productId && c.有効フラグ);
      if (cost) {
        container.querySelector('#material-cost').value = cost.材料費 || 0;
        container.querySelector('#labor-cost').value = cost.労務費 || 0;
        container.querySelector('#overhead-cost').value = cost.製造間接費 || 0;
        container.querySelector('#total-cost').value = cost.総原価 || 0;
      }
    });
  }

  // 市場分析更新
  function updateMarketAnalysis() {
    const productId = container.querySelector('#product-select').value;
    if (!productId) return;

    window.aivicApi.list(8).then(competitorPrices => {
      const relevantPrices = competitorPrices.filter(p => p.製品ID === productId && p.有効フラグ);

      if (relevantPrices.length > 0) {
        const prices = relevantPrices.map(p => p.価格);
        const avgPrice = Math.round(prices.reduce((a, b) => a + b, 0) / prices.length);
        const maxPrice = Math.max(...prices);
        const minPrice = Math.min(...prices);

        container.querySelector('#market-avg-price').textContent = `¥${avgPrice.toLocaleString()}`;
        container.querySelector('#competitor-max-price').textContent = `¥${maxPrice.toLocaleString()}`;
        container.querySelector('#competitor-min-price').textContent = `¥${minPrice.toLocaleString()}`;

        renderCompetitorPrices(relevantPrices);
      }
    });
  }

  // 最適価格算出
  function calculateOptimalPrice() {
    const totalCost = parseInt(container.querySelector('#total-cost').value) || 0;
    const targetProfitRate = parseInt(container.querySelector('#target-profit-rate').value) || 0;
    const minProfitRate = parseInt(container.querySelector('#min-profit-rate').value) || 0;

    if (totalCost === 0) {
      alert('原価情報を確認してください');
      return;
    }

    // 目標利益率での価格
    const targetPrice = Math.round(totalCost / (1 - targetProfitRate / 100));

    // 市場価格との比較調整
    const marketAvg = parseInt(container.querySelector('#market-avg-price').textContent.replace(/[¥,]/g, '')) || targetPrice;
    const adjustedPrice = Math.round((targetPrice + marketAvg) / 2);

    // 最低利益率チェック
    const actualProfitRate = ((adjustedPrice - totalCost) / adjustedPrice) * 100;

    if (actualProfitRate < minProfitRate) {
      const minPrice = Math.round(totalCost / (1 - minProfitRate / 100));
      container.querySelector('#recommended-price').textContent = `¥${minPrice.toLocaleString()}`;
      container.querySelector('#expected-profit-rate').textContent = `${minProfitRate.toFixed(1)}%`;
    } else {
      container.querySelector('#recommended-price').textContent = `¥${adjustedPrice.toLocaleString()}`;
      container.querySelector('#expected-profit-rate').textContent = `${actualProfitRate.toFixed(1)}%`;
    }

    // 競合比較
    const competitorComparison = ((adjustedPrice - marketAvg) / marketAvg * 100).toFixed(1);
    container.querySelector('#competitor-comparison').textContent = `${competitorComparison > 0 ? '+' : ''}${competitorComparison}%`;

    // リスク評価
    const risk = Math.abs(competitorComparison) < 5 ? '低' : Math.abs(competitorComparison) < 10 ? '中' : '高';
    container.querySelector('#risk-assessment').textContent = risk;
  }

  // CSVエクスポート
  function exportAnalysisCSV() {
    const data = [
      ['項目', '値'],
      ['製品', container.querySelector('#product-select').selectedOptions[0]?.text || ''],
      ['市場平均価格', container.querySelector('#market-avg-price').textContent],
      ['推奨販売価格', container.querySelector('#recommended-price').textContent],
      ['予想利益率', container.querySelector('#expected-profit-rate').textContent],
      ['競合比較', container.querySelector('#competitor-comparison').textContent],
      ['リスク評価', container.querySelector('#risk-assessment').textContent]
    ];

    const csv = '\uFEFF' + data.map(row => row.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'price_analysis.csv';
    a.click();
    URL.revokeObjectURL(url);
  }

  // 初期データ読み込み
  renderCompetitorPrices(tables[8]?.records || []);
  drawPriceChart('competitor');

  // イベントリスナー
  container.querySelector('#product-select').addEventListener('change', (e) => {
    updateCostInfo(e.target.value);
    updateMarketAnalysis();
  });

  container.querySelector('#min-profit-rate').addEventListener('input', (e) => {
    container.querySelector('#min-profit-display').textContent = `${e.target.value}%`;
  });

  container.querySelector('#refresh-competitor-btn').addEventListener('click', () => {
    window.aivicApi.list(8).then(renderCompetitorPrices);
  });

  container.querySelector('#view-competitor-price-btn').addEventListener('click', () => {
    drawPriceChart('competitor');
    container.querySelector('#view-competitor-price-btn').className = 'action-btn text-xs px-2 py-1';
    container.querySelector('#view-self-price-btn').className = 'action-btn secondary text-xs px-2 py-1';
  });

  container.querySelector('#view-self-price-btn').addEventListener('click', () => {
    drawPriceChart('self');
    container.querySelector('#view-self-price-btn').className = 'action-btn text-xs px-2 py-1';
    container.querySelector('#view-competitor-price-btn').className = 'action-btn secondary text-xs px-2 py-1';
  });

  container.querySelector('#calculate-price-btn').addEventListener('click', calculateOptimalPrice);

  container.querySelector('#export-analysis-btn').addEventListener('click', exportAnalysisCSV);

  container.querySelector('#save-price-btn').addEventListener('click', async () => {
    const productId = container.querySelector('#product-select').value;
    const recommendedPrice = container.querySelector('#recommended-price').textContent.replace(/[¥,]/g, '');

    if (!productId || !recommendedPrice) {
      alert('製品と価格を確認してください');
      return;
    }

    const priceData = {
      商品ID: productId,
      仕入先ID: 'supplier-001', // デフォルト
      適用開始日: new Date().toISOString(),
      単価: parseInt(recommendedPrice),
      価格変更理由: '競合分析による最適価格設定',
      有効フラグ: true,
      作成者: 'system'
    };

    const saved = await window.aivicApi.save(1, priceData);
    if (saved) {
      alert('価格が保存されました');
    }
  });

  // 初期表示更新
  updateMarketAnalysis();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#order-tbody");
  let currentOrderId = null;
  let allOrders = [];

  // ステータスバッジのスタイル取得
  function getStatusBadge(status) {
    const statusStyles = {
      '受注確定': 'bg-blue-500 text-white',
      '製造中': 'bg-yellow-500 text-white',
      '出荷済み': 'bg-green-500 text-white',
      '完了': 'bg-gray-500 text-white',
      'キャンセル': 'bg-red-500 text-white'
    };
    const style = statusStyles[status] || 'bg-gray-400 text-white';
    return `<span class="px-2 py-1 rounded text-xs font-medium ${style}">${status || ''}</span>`;
  }

  // 金額フォーマット
  function formatAmount(amount) {
    if (!amount) return '¥0';
    return '¥' + parseInt(amount).toLocaleString();
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // 1. テーブル再描画関数
  function renderRows(rows) {
    allOrders = rows;
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" class="border-b border-[rgba(255,255,255,0.08)] hover:bg-[rgba(255,255,255,0.03)] cursor-pointer">
        <td class="px-4 py-3 text-sm text-[var(--text)] font-medium">${r.受注番号 || ''}</td>
        <td class="px-4 py-3 text-sm text-[var(--text)]">${r.顧客名 || ''}</td>
        <td class="px-4 py-3 text-sm text-[var(--text)]">${formatDate(r.受注日)}</td>
        <td class="px-4 py-3 text-sm text-[var(--text)]">${formatDate(r.納期)}</td>
        <td class="px-4 py-3 text-sm text-[var(--text)] text-right font-medium">${formatAmount(r.受注金額)}</td>
        <td class="px-4 py-3 text-center">${getStatusBadge(r.受注ステータス)}</td>
        <td class="px-4 py-3 text-center">
          <button class="action-btn secondary view-detail-btn text-xs" data-id="${r.id}">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データ描画
  renderRows(tables[4]?.records || []);

  // 検索フィルタ関数
  function filterOrders() {
    const orderNumber = container.querySelector("#order-number-search").value.toLowerCase();
    const customerName = container.querySelector("#customer-name-search").value.toLowerCase();
    const dateFrom = container.querySelector("#order-date-from").value;
    const dateTo = container.querySelector("#order-date-to").value;
    const status = container.querySelector("#order-status-filter").value;

    let filtered = allOrders.filter(order => {
      // 受注番号フィルタ
      if (orderNumber && !(order.受注番号 || '').toLowerCase().includes(orderNumber)) {
        return false;
      }

      // 顧客名フィルタ
      if (customerName && !(order.顧客名 || '').toLowerCase().includes(customerName)) {
        return false;
      }

      // 受注日フィルタ
      if (dateFrom || dateTo) {
        const orderDate = new Date(order.受注日);
        if (dateFrom && orderDate < new Date(dateFrom)) return false;
        if (dateTo && orderDate > new Date(dateTo)) return false;
      }

      // ステータスフィルタ
      if (status && order.受注ステータス !== status) {
        return false;
      }

      return true;
    });

    renderRows(filtered);
  }

  // 詳細表示関数
  function showOrderDetail(orderId) {
    const order = allOrders.find(o => o.id === orderId);
    if (!order) return;

    currentOrderId = orderId;

    container.querySelector("#detail-order-number").textContent = order.受注番号 || '';
    container.querySelector("#detail-customer-name").textContent = order.顧客名 || '';
    container.querySelector("#detail-sales-rep").textContent = order.担当営業名 || '';
    container.querySelector("#detail-order-date").textContent = formatDate(order.受注日);
    container.querySelector("#detail-delivery-date").textContent = formatDate(order.納期);
    container.querySelector("#detail-order-amount").textContent = formatAmount(order.受注金額);
    container.querySelector("#detail-notes").textContent = order.備考 || '';

    container.querySelector("#order-detail-panel").style.display = "block";
  }

  // CSVエクスポート関数
  function exportToCSV() {
    const headers = ['受注番号', '顧客名', '受注日', '納期', '受注金額', '受注ステータス', '担当営業', '備考'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allOrders.map(order => [
        `"${order.受注番号 || ''}"`,
        `"${order.顧客名 || ''}"`,
        `"${formatDate(order.受注日)}"`,
        `"${formatDate(order.納期)}"`,
        `"${order.受注金額 || 0}"`,
        `"${order.受注ステータス || ''}"`,
        `"${order.担当営業名 || ''}"`,
        `"${(order.備考 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `受注一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 3. 検索ボタンイベント
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(4);
    if (rows) {
      allOrders = rows;
      filterOrders();
    }
  });

  // クリアボタンイベント
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#order-number-search").value = '';
    container.querySelector("#customer-name-search").value = '';
    container.querySelector("#order-date-from").value = '';
    container.querySelector("#order-date-to").value = '';
    container.querySelector("#order-status-filter").value = '';
    renderRows(allOrders);
  });

  // CSVエクスポートボタンイベント
  container.querySelector("#btn-export").addEventListener("click", exportToCSV);

  // 新規受注登録ボタンイベント
