function(container, apiUrl, tables) {
  const tbody = container.querySelector("#request-tbody");

  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}" style="cursor: pointer; border-bottom: 1px solid var(--border);" 
          onmouseover="this.style.background='rgba(255,255,255,0.03)'" 
          onmouseout="this.style.background='transparent'">
        <td style="padding: 10px 12px; color: var(--text);">${r.要求ID || r.id || ''}</td>
        <td style="padding: 10px 12px; color: var(--text);">${r.顧客名 || r.customerName || ''}</td>
        <td style="padding: 10px 12px; color: var(--text);">${r.製品名 || r.productName || ''}</td>
        <td style="padding: 10px 12px; color: var(--text);">${r.数量 || r.quantity || ''}</td>
        <td style="padding: 10px 12px; color: var(--text);">${r.希望納期 || r.deliveryDate || ''}</td>
        <td style="padding: 10px 12px;">
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 11px; font-weight: 500; 
                       background: ${getStatusColor(r.ステータス || r.status)}; color: #fff;">
            ${r.ステータス || r.status || ''}
          </span>
        </td>
        <td style="padding: 10px 12px; color: var(--text);">${r.担当営業 || r.salesPerson || ''}</td>
        <td style="padding: 10px 12px;">
          <button class="edit-btn action-btn secondary" data-id="${r.id || ''}" 
                  style="padding: 4px 8px; margin-right: 4px; background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); border-radius: 3px; font-size: 11px; cursor: pointer;">
            編集
          </button>
          <button class="delete-btn action-btn secondary" data-id="${r.id || ''}" 
                  style="padding: 4px 8px; background: transparent; color: #ff6b6b; border: 1px solid #ff6b6b; border-radius: 3px; font-size: 11px; cursor: pointer;">
            削除
          </button>
        </td>
      </tr>
    `).join("");
  }

  function getStatusColor(status) {
    switch(status) {
      case '新規': return '#3b82f6';
      case '検討中': return '#f59e0b';
      case '見積済み': return '#8b5cf6';
      case '受注': return '#10b981';
      case '失注': return '#ef4444';
      default: return '#6b7280';
    }
  }

  // 2. 初期データを即座に描画
  renderRows(tables[0]?.records || []);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const customerSearch = container.querySelector("#customer-search").value.toLowerCase();
    const statusFilter = container.querySelector("#status-filter").value;
    const salesFilter = container.querySelector("#sales-filter").value;

    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = rows.filter(r => {
        const matchCustomer = !customerSearch || (r.顧客名 || r.customerName || '').toLowerCase().includes(customerSearch);
        const matchStatus = !statusFilter || (r.ステータス || r.status) === statusFilter;
        const matchSales = !salesFilter || (r.担当営業 || r.salesPerson) === salesFilter;
        return matchCustomer && matchStatus && matchSales;
      });
      renderRows(filtered);
    }
  });

  // 4. 保存ボタンのイベントリスナー
  container.querySelector("#btn-save").addEventListener("click", async (e) => {
    e.preventDefault();

    const editId = container.querySelector("#edit-id").value;
    const customerName = container.querySelector("#customer-select").value;
    const productName = container.querySelector("#product-select").value;
    const quantity = container.querySelector("#quantity-input").value;
    const deliveryDate = container.querySelector("#delivery-date").value;
    const status = container.querySelector("#status-select").value;
    const salesPerson = container.querySelector("#sales-select").value;
    const notes = container.querySelector("#notes-input").value;

    if (!customerName || !productName || !quantity || !deliveryDate || !status || !salesPerson) {
      alert("必須項目を入力してください");
      return;
    }

    const data = {
      顧客名: customerName,
      customerName: customerName,
      製品名: productName,
      productName: productName,
      数量: parseInt(quantity),
      quantity: parseInt(quantity),
      希望納期: deliveryDate,
      deliveryDate: deliveryDate,
      ステータス: status,
      status: status,
      担当営業: salesPerson,
      salesPerson: salesPerson,
      備考: notes,
      notes: notes,
      要求ID: editId || `REQ-${Date.now()}`,
      id: editId || undefined
    };

    let result;
    if (editId) {
      result = await window.aivicApi.update(0, editId, data);
    } else {
      result = await window.aivicApi.save(0, data);
    }

    if (result) {
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);

      // フォームクリア
      container.querySelector("#request-form").reset();
      container.querySelector("#edit-id").value = "";
    }
  });

  // 5. クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#request-form").reset();
    container.querySelector("#edit-id").value = "";
  });

  // 6. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この要求を削除しますか？")) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);

      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const record = rows.find(r => r.id === id);
        if (record) {
          container.querySelector("#edit-id").value = record.id;
          container.querySelector("#customer-select").value = record.顧客名 || record.customerName || '';
          container.querySelector("#product-select").value = record.製品名 || record.productName || '';
          container.querySelector("#quantity-input").value = record.数量 || record.quantity || '';
          container.querySelector("#delivery-date").value = record.希望納期 || record.deliveryDate || '';
          container.querySelector("#status-select").value = record.ステータス || record.status || '';
          container.querySelector("#sales-select").value = record.担当営業 || record.salesPerson || '';
          container.querySelector("#notes-input").value = record.備考 || record.notes || '';
        }
      }
      return;
    }

    // 行クリック（詳細表示）
    const row = e.target.closest("tr[data-id]");
    if (row && !e.target.closest("button")) {
      const id = row.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const record = rows.find(r => r.id === id);
        if (record) {
          container.querySelector("#edit-id").value = record.id;
          container.querySelector("#customer-select").value = record.顧客名 || record.customerName || '';
          container.querySelector("#product-select").value = record.製品名 || record.productName || '';
          container.querySelector("#quantity-input").value = record.数量 || record.quantity || '';
          container.querySelector("#delivery-date").value = record.希望納期 || record.deliveryDate || '';
          container.querySelector("#status-select").value = record.ステータス || record.status || '';
          container.querySelector("#sales-select").value = record.担当営業 || record.salesPerson || '';
          container.querySelector("#notes-input").value = record.備考 || record.notes || '';
        }
      }
    }
  });

  // 7. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (rows && rows.length > 0) {
      const headers = ["要求ID", "顧客名", "製品名", "数量", "希望納期", "ステータス", "担当営業", "備考"];
      const csvContent = [
        headers.join(","),
        ...rows.map(r => [
          r.要求ID || r.id || '',
          r.顧客名 || r.customerName || '',
          r.製品名 || r.productName || '',
          r.数量 || r.quantity || '',
          r.希望納期 || r.deliveryDate || '',
          r.ステータス || r.status || '',
          r.担当営業 || r.salesPerson || '',
          (r.備考 || r.notes || '').replace(/,/g, '，')
        ].map(field => `"${field}"`).join(","))
      ].join("\n");

      const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `顧客要求一覧_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    }
  });

  // 8. アクションボタン
  container.querySelector("#btn-quote").addEventListener("click", () => {
    window.showScreen("scr-1780996206790"); // 納期回答作成画面
