function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const ORDER_TABLE = 5; // 受注テーブル
  const PRODUCT_TABLE = 3; // 製品テーブル
  const CUSTOMER_TABLE = 2; // 顧客テーブル

  // DOM要素取得
  const orderSelect = container.querySelector('#order-select');
  const customerNameInput = container.querySelector('#customer-name');
  const orderDateInput = container.querySelector('#order-date');
  const productTbody = container.querySelector('#product-tbody');
  const productionLineSelect = container.querySelector('#production-line-select');
  const prioritySelect = container.querySelector('#priority-select');
  const estimatedDeliveryInput = container.querySelector('#estimated-delivery');
  const adjustedDeliveryInput = container.querySelector('#adjusted-delivery');
  const deliveryDiffInput = container.querySelector('#delivery-diff');
  const deliveryReasonTextarea = container.querySelector('#delivery-reason');
  const customerCommentTextarea = container.querySelector('#customer-comment');
  const calculateDeliveryBtn = container.querySelector('#calculate-delivery-btn');
  const saveResponseBtn = container.querySelector('#save-response-btn');

  // プレビュー要素
  const previewDate = container.querySelector('#preview-date');
  const previewCustomer = container.querySelector('#preview-customer');
  const previewProducts = container.querySelector('#preview-products');
  const previewDelivery = container.querySelector('#preview-delivery');
  const previewComment = container.querySelector('#preview-comment');

  // 受注データ再描画
  function renderOrderOptions(orders) {
    const options = orders.map(order => 
      `<option value="${order.受注ID}">${order.受注番号 || ''}</option>`
    ).join('');
    orderSelect.innerHTML = '<option value="">選択してください</option>' + options;
  }

  // 製品明細再描画
  function renderProductDetails(products) {
    if (!products || products.length === 0) {
      productTbody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: var(--text-muted);">製品明細がありません</td></tr>';
      return;
    }

    productTbody.innerHTML = products.map(product => `
      <tr>
        <td>${product.製品コード || ''}</td>
        <td>${product.製品名 || ''}</td>
        <td>${product.数量 || 0}</td>
        <td>¥${(product.単価 || 0).toLocaleString()}</td>
        <td>¥${(product.金額 || 0).toLocaleString()}</td>
        <td>${product.標準納期 || '-'}日</td>
      </tr>
    `).join('');
  }

  // プレビュー更新
  function updatePreview() {
    const today = new Date().toISOString().split('T')[0];
    previewDate.textContent = today;
    previewCustomer.textContent = customerNameInput.value || '未選択';

    const adjustedDate = adjustedDeliveryInput.value;
    if (adjustedDate) {
      const date = new Date(adjustedDate);
      previewDelivery.textContent = `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
    } else {
      previewDelivery.textContent = '未設定';
    }

    previewComment.textContent = customerCommentTextarea.value || 'お客様のご要望にお応えできるよう、最適な生産スケジュールを調整いたします。';
  }

  // 納期差異計算
  function calculateDeliveryDiff() {
    const estimated = estimatedDeliveryInput.value;
    const adjusted = adjustedDeliveryInput.value;

    if (estimated && adjusted) {
      const estimatedDate = new Date(estimated);
      const adjustedDate = new Date(adjusted);
      const diffTime = adjustedDate - estimatedDate;
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      if (diffDays > 0) {
        deliveryDiffInput.value = `+${diffDays}日`;
        deliveryDiffInput.style.color = '#f87171';
      } else if (diffDays < 0) {
        deliveryDiffInput.value = `${diffDays}日`;
        deliveryDiffInput.style.color = '#4ade80';
      } else {
        deliveryDiffInput.value = '±0日';
        deliveryDiffInput.style.color = 'var(--text)';
      }
    } else {
      deliveryDiffInput.value = '';
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const orders = await window.aivicApi.list(ORDER_TABLE);
      if (orders) {
        renderOrderOptions(orders);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 受注選択時の処理
  orderSelect.addEventListener('change', async function() {
    const orderId = this.value;
    if (!orderId) {
      customerNameInput.value = '';
      orderDateInput.value = '';
      renderProductDetails([]);
      return;
    }

    try {
      const orders = await window.aivicApi.list(ORDER_TABLE);
      const selectedOrder = orders?.find(order => order.受注ID === orderId);

      if (selectedOrder) {
        customerNameInput.value = selectedOrder.顧客名 || '';
        orderDateInput.value = selectedOrder.受注日 ? selectedOrder.受注日.split('T')[0] : '';

        // 製品明細の模擬データ（実際は受注明細テーブルから取得）
        const mockProducts = [
          {
            製品コード: 'PRD-001',
            製品名: '高精度センサー',
            数量: 50,
            単価: 25000,
            金額: 1250000,
            標準納期: 14
          },
          {
            製品コード: 'PRD-002',
            製品名: '制御ユニット',
            数量: 20,
            単価: 85000,
            金額: 1700000,
            標準納期: 21
          }
        ];
        renderProductDetails(mockProducts);
      }
    } catch (error) {
      console.error('受注データ取得エラー:', error);
    }

    updatePreview();
  });

  // 納期計算ボタン
  calculateDeliveryBtn.addEventListener('click', function() {
    const productionLine = productionLineSelect.value;
    const priority = prioritySelect.value;

    if (!productionLine) {
      alert('生産ラインを選択してください');
      return;
    }

    // 模擬的な納期計算（実際は生産計画APIを呼び出し）
    const baseDate = new Date();
    let deliveryDays = 21; // 基本納期

    // 優先度による調整
    if (priority === '1') {
      deliveryDays -= 3; // 高優先は3日短縮
    } else if (priority === '3') {
      deliveryDays += 5; // 低優先は5日延長
    }

    // 生産ラインによる調整
    if (productionLine === 'LINE-A') {
      deliveryDays -= 2; // 専用ラインは2日短縮
    } else if (productionLine === 'LINE-C') {
      deliveryDays += 3; // 汎用ラインは3日延長
    }

    const deliveryDate = new Date(baseDate);
    deliveryDate.setDate(deliveryDate.getDate() + deliveryDays);

    estimatedDeliveryInput.value = deliveryDate.toISOString().split('T')[0];
    adjustedDeliveryInput.value = deliveryDate.toISOString().split('T')[0];

    calculateDeliveryDiff();
    updatePreview();
  });

  // 調整納期変更時の処理
  adjustedDeliveryInput.addEventListener('change', function() {
    calculateDeliveryDiff();
    updatePreview();
  });

  // コメント変更時の処理
  customerCommentTextarea.addEventListener('input', updatePreview);

  // 納期回答保存ボタン
  saveResponseBtn.addEventListener('click', async function() {
    const orderId = orderSelect.value;
    const adjustedDelivery = adjustedDeliveryInput.value;
    const deliveryReason = deliveryReasonTextarea.value;
    const customerComment = customerCommentTextarea.value;

    if (!orderId) {
      alert('受注を選択してください');
      return;
    }

    if (!adjustedDelivery) {
      alert('納期を設定してください');
      return;
    }

    try {
      // 受注テーブルの納期を更新
      const updated = await window.aivicApi.update(ORDER_TABLE, orderId, {
        納期: adjustedDelivery,
        備考: `${deliveryReason ? '納期理由: ' + deliveryReason + '\n' : ''}${customerComment ? '顧客コメント: ' + customerComment : ''}`
      });

      if (updated) {
        alert('納期回答を保存しました');
      } else {
        alert('保存に失敗しました');
      }
    } catch (error) {
      console.error('保存エラー:', error);
      alert('保存中にエラーが発生しました');
    }
  });

  // 初期化
  loadInitialData();
  updatePreview();
}

function(container, apiUrl, tables) {
