    tbody.innerHTML = orders.map(order => {
      const customer = tables[2].records.find(c => c.id === order.顧客ID) || {};
      const salesUser = tables[0].records.find(u => u.id === order.担当営業ID) || {};
      const profitData = tables[10].records.find(p => p.受注ID === order.id) || {};

      return `
        <tr data-id="${order.id}">
          <td>${order.受注番号 || ""}</td>
          <td>${order.受注日 ? new Date(order.受注日).toLocaleDateString() : ""}</td>
