          <td>
            <button class="text-blue-400 hover:underline" onclick="window.showScreen('scr-1780996186885')" data-id="${order.id}">
              ${order.製品名 || "詳細を見る"}
            </button>
          </td>
          <td>${order.数量 || 0}個</td>
          <td>¥${(order.受注金額 || 0).toLocaleString()}</td>
          <td>${profitData.利益率 ? (profitData.利益率 / 100).toFixed(1) + "%" : "-"}</td>
          <td>${salesUser.氏名 || ""}</td>
          <td>
            <span class="px-2 py-1 rounded text-xs" style="background: ${getStatusColor(order.受注ステータス)}; color: #fff;">
              ${order.受注ステータス || ""}
            </span>
          </td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${order.id}" onclick="window.showScreen('scr-1780996145775')">編集</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  function getStatusColor(status) {
    const colors = {
      "受注確定": "#10b981",
      "製造中": "#f59e0b", 
      "出荷済み": "#3b82f6",
      "完了": "#6b7280"
    };
    return colors[status] || "#6b7280";
  }

  // KPI更新関数
  function updateKPIs(orders) {
    const totalAmount = orders.reduce((sum, o) => sum + (o.受注金額 || 0), 0);
    const orderCount = orders.length;
    const avgPrice = orderCount > 0 ? totalAmount / orderCount : 0;

    const profitRates = orders.map(o => {
      const profit = tables[10].records.find(p => p.受注ID === o.id);
      return profit ? profit.利益率 / 100 : 0;
    }).filter(r => r > 0);
    const avgProfitRate = profitRates.length > 0 ? profitRates.reduce((sum, r) => sum + r, 0) / profitRates.length : 0;

    container.querySelector("#total-amount").textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector("#order-count").textContent = `${orderCount}件`;
    container.querySelector("#avg-price").textContent = `¥${Math.round(avgPrice).toLocaleString()}`;
    container.querySelector("#profit-rate").textContent = `${(avgProfitRate * 100).toFixed(1)}%`;

    // 前年同期比（サンプル）
    container.querySelector("#amount-growth").textContent = "+12.5%";
    container.querySelector("#count-growth").textContent = "+8.3%";
    container.querySelector("#price-growth").textContent = "+3.7%";
    container.querySelector("#rate-growth").textContent = "+1.2%";
  }

  // チャート描画関数
  function drawAmountChart(orders) {
    const canvas = container.querySelector("#amount-chart");
    const ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2;
    canvas.height = rect.height * 2;
    ctx.scale(2, 2);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 月別集計
    const monthlyData = {};
    orders.forEach(order => {
      if (order.受注日) {
        const month = new Date(order.受注日).toISOString().slice(0, 7);
        monthlyData[month] = (monthlyData[month] || 0) + (order.受注金額 || 0);
      }
    });

    const months = Object.keys(monthlyData).sort();
    const amounts = months.map(m => monthlyData[m]);

    if (months.length === 0) return;

    const maxAmount = Math.max(...amounts);
    const chartWidth = rect.width - 60;
    const chartHeight = rect.height - 60;

    // 軸
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(40, 20);
    ctx.lineTo(40, chartHeight + 20);
    ctx.lineTo(chartWidth + 40, chartHeight + 20);
    ctx.stroke();

    // データ線
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();

    amounts.forEach((amount, i) => {
      const x = 40 + (i * chartWidth / (amounts.length - 1));
      const y = 20 + chartHeight - (amount / maxAmount * chartHeight);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    months.forEach((month, i) => {
      const x = 40 + (i * chartWidth / (amounts.length - 1));
      ctx.fillText(month.slice(5), x - 10, chartHeight + 35);
    });
  }

  function drawProductChart(orders) {
    const canvas = container.querySelector("#product-chart");
    const ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2;
    canvas.height = rect.height * 2;
    ctx.scale(2, 2);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 製品別集計
    const productData = {};
    orders.forEach(order => {
      const details = tables[6].records.filter(d => d.受注ID === order.id);
      details.forEach(detail => {
        const product = tables[3].records.find(p => p.id === detail.製品ID);
        if (product) {
          const category = product.カテゴリ || "その他";
          productData[category] = (productData[category] || 0) + (detail.数量 || 0);
        }
      });
    });

    const categories = Object.keys(productData);
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

    let total = Object.values(productData).reduce((sum, val) => sum + val, 0);
    if (total === 0) return;

    let startAngle = 0;
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;
    const radius = Math.min(centerX, centerY) - 40;

    categories.forEach((category, i) => {
      const value = productData[category];
      const angle = (value / total) * 2 * Math.PI;

      ctx.fillStyle = colors[i % colors.length];
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + angle);
      ctx.closePath();
      ctx.fill();

      // ラベル
      const labelAngle = startAngle + angle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius + 20);
      const labelY = centerY + Math.sin(labelAngle) * (radius + 20);

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.fillText(`${category}: ${value}`, labelX - 20, labelY);

      startAngle += angle;
    });
  }

  function drawProfitChart(orders) {
    const canvas = container.querySelector("#profit-chart");
    const ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2;
    canvas.height = rect.height * 2;
    ctx.scale(2, 2);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 月別利益率集計
    const monthlyProfit = {};
    orders.forEach(order => {
      if (order.受注日) {
        const month = new Date(order.受注日).toISOString().slice(0, 7);
        const profitData = tables[10].records.find(p => p.受注ID === order.id);
        if (profitData) {
          if (!monthlyProfit[month]) monthlyProfit[month] = [];
          monthlyProfit[month].push(profitData.利益率 / 100);
        }
      }
    });

    const months = Object.keys(monthlyProfit).sort();
    const avgRates = months.map(m => {
      const rates = monthlyProfit[m];
      return rates.reduce((sum, r) => sum + r, 0) / rates.length;
    });

    if (months.length === 0) return;

    const maxRate = Math.max(...avgRates, 0.3);
    const chartWidth = rect.width - 60;
    const chartHeight = rect.height - 60;

    // 軸
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(40, 20);
    ctx.lineTo(40, chartHeight + 20);
    ctx.lineTo(chartWidth + 40, chartHeight + 20);
    ctx.stroke();

    // データ線
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 2;
    ctx.beginPath();

    avgRates.forEach((rate, i) => {
      const x = 40 + (i * chartWidth / (avgRates.length - 1));
      const y = 20 + chartHeight - (rate / maxRate * chartHeight);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    months.forEach((month, i) => {
      const x = 40 + (i * chartWidth / (avgRates.length - 1));
      ctx.fillText(month.slice(5), x - 10, chartHeight + 35);
    });
  }

  // 顧客ランキング更新
  function updateCustomerRanking(orders) {
    const customerSales = {};
    orders.forEach(order => {
      const customer = tables[2].records.find(c => c.id === order.顧客ID);
      if (customer) {
        customerSales[customer.顧客名] = (customerSales[customer.顧客名] || 0) + (order.受注金額 || 0);
      }
    });

    const ranking = Object.entries(customerSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 5);

    const rankingEl = container.querySelector("#customer-ranking");
    rankingEl.innerHTML = ranking.map(([name, amount], i) => `
      <div class="flex justify-between items-center p-2 rounded" style="background: rgba(59, 130, 246, 0.1);">
        <div class="flex items-center gap-2">
          <span class="w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold" style="background: var(--primary); color: #fff;">
            ${i + 1}
          </span>
          <span style="color: var(--text);">${name}</span>
        </div>
        <span class="font-semibold" style="color: var(--text);">¥${amount.toLocaleString()}</span>
      </div>
    `).join("");
  }

  // 営業担当者ランキング更新
  function updateSalesRanking(orders) {
    const salesPerformance = {};
    orders.forEach(order => {
      const user = tables[0].records.find(u => u.id === order.担当営業ID);
      if (user) {
        salesPerformance[user.氏名] = (salesPerformance[user.氏名] || 0) + (order.受注金額 || 0);
      }
    });

    const ranking = Object.entries(salesPerformance)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 5);

    const rankingEl = container.querySelector("#sales-ranking");
    rankingEl.innerHTML = ranking.map(([name, amount], i) => `
      <div class="card p-2 text-center">
        <div class="text-xs" style="color: var(--text-muted);">#${i + 1}</div>
        <div class="font-semibold text-sm" style="color: var(--text);">${name}</div>
        <div class="text-xs font-bold" style="color: var(--primary);">¥${Math.round(amount / 10000)}万</div>
      </div>
    `).join("");
  }

  // 初期データ描画
  const initialOrders = tables[4].records || [];
  renderOrderRows(initialOrders);
  updateKPIs(initialOrders);
  drawAmountChart(initialOrders);
  drawProductChart(initialOrders);
  drawProfitChart(initialOrders);
  updateCustomerRanking(initialOrders);
  updateSalesRanking(initialOrders);

  // 分析実行ボタン
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    const period = container.querySelector("#period-filter").value;
    const customer = container.querySelector("#customer-filter").value;
    const category = container.querySelector("#category-filter").value;

    const orders = await window.aivicApi.list(4);
    if (!orders) return;

    let filteredOrders = orders;

    // 期間フィルタ
    if (period && period !== "custom") {
      const now = new Date();
      let startDate;
      switch (period) {
        case "last-month":
          startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
          break;
        case "last-3months":
          startDate = new Date(now.getFullYear(), now.getMonth() - 3, 1);
          break;
        case "last-6months":
          startDate = new Date(now.getFullYear(), now.getMonth() - 6, 1);
          break;
        case "last-year":
          startDate = new Date(now.getFullYear() - 1, now.getMonth(), 1);
          break;
      }
      if (startDate) {
        filteredOrders = filteredOrders.filter(o => o.受注日 && new Date(o.受注日) >= startDate);
      }
    }

    // 顧客フィルタ
    if (customer) {
      filteredOrders = filteredOrders.filter(o => o.顧客ID === customer);
    }

    // カテゴリフィルタ
    if (category) {
      const categoryProducts = tables[3].records.filter(p => p.カテゴリ === category).map(p => p.id);
      const categoryOrderIds = tables[6].records
        .filter(d => categoryProducts.includes(d.製品ID))
        .map(d => d.受注ID);
      filteredOrders = filteredOrders.filter(o => categoryOrderIds.includes(o.id));
    }

    renderOrderRows(filteredOrders);
    updateKPIs(filteredOrders);
    drawAmountChart(filteredOrders);
    drawProductChart(filteredOrders);
    drawProfitChart(filteredOrders);
    updateCustomerRanking(filteredOrders);
    updateSalesRanking(filteredOrders);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const orders = await window.aivicApi.list(4);
    if (!orders) return;

    const csvData = [
      ["受注番号", "受注日", "顧客名", "受注金額", "受注ステータス", "担当営業", "納期"]
    ];

    orders.forEach(order => {
      const customer = tables[2].records.find(c => c.id === order.顧客ID) || {};
      const salesUser = tables[0].records.find(u => u.id === order.担当営業ID) || {};

      csvData.push([
        order.受注番号 || "",
        order.受注日 ? new Date(order.受注日).toLocaleDateString() : "",
        customer.顧客名 || "",
        order.受注金額 || 0,
        order.受注ステータス || "",
        salesUser.氏名 || "",
        order.納期 ? new Date(order.納期).toLocaleDateString() : ""
      ]);
    });

    const csvContent = "\uFEFF" + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(",")
    ).join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "受注履歴分析_" + new Date().toISOString().slice(0, 10) + ".csv";
    link.click();
  });
}
